var calc_output = [];

var a = parseFloat(a);
var b = parseFloat(b);
var c = parseFloat(c);


// Calculate score
var score = a + b + c;

var risk;
if (score <= 6) {
    risk = 'Mild';
} else if (score >= 7 && score <= 12) {
    risk = 'Moderate';
} else if (score >= 13) {
    risk = 'Severe';
}

// Output
calc_output.push({
    name: 'mini',
    value: score,
    value_text: 'points',
    message: 'NVP severity: ' + risk 
});
